<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://hawaiiinsuranceappraiser.com/#business","name":"Hawaii Insurance Appraiser","url":"https://hawaiiinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@hawaiiinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://hawaiiinsuranceappraiser.com/#logo","url":"https://hawaiiinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Hawaii Insurance Appraiser"},"image":{"@id":"https://hawaiiinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"HI","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@hawaiiinsuranceappraiser.com","contactType":"customer service","areaServed":"US-HI","availableLanguage":"en"}],"slogan":"Independent appraisal for underpaid island property claims","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims on Oahu, Hawaii Island, Maui, Kauai, Molokai and Lanai.","areaServed":[{"@type":"State","name":"Hawaii"},{"@type":"City","name":"Honolulu"},{"@type":"City","name":"Kaneohe"},{"@type":"City","name":"Pearl City"},{"@type":"City","name":"Kapolei"},{"@type":"City","name":"Mililani"},{"@type":"City","name":"Hilo"},{"@type":"City","name":"Kailua-Kona"},{"@type":"City","name":"Pahoa"},{"@type":"City","name":"Kahului"},{"@type":"City","name":"Kihei"},{"@type":"City","name":"Lahaina"},{"@type":"City","name":"Lihue"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/appraisal-clause-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/homeowner-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, AOAO & Commercial","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/condo-aoao-commercial-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/roof-hail-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Kona Storm & High-Wind Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/kona-storm-high-wind-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane Claim Appraisal","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/hurricane-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/fire-smoke-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Volcanic, Ash & Lava Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/volcanic-ashfall-lava-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hurricane deductibles","Condominium master policies","Wildfire claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"07:00","closes":"17:00"}]},{"@type":"WebSite","@id":"https://hawaiiinsuranceappraiser.com/#website","url":"https://hawaiiinsuranceappraiser.com/","name":"Hawaii Insurance Appraiser","publisher":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#webpage","url":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/","name":"Insurance Appraisal FAQ by Topic | Hawaii Owners","description":"Insurance appraisal FAQ for Hawaii owners, grouped by topic: basics, costs, deadlines, HPIA, hurricane deductibles and condo policies.","inLanguage":"en-US","isPartOf":{"@id":"https://hawaiiinsuranceappraiser.com/#website"},"about":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"publisher":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","primaryImageOfPage":{"@type":"ImageObject","@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#primaryimage","url":"https://hawaiiinsuranceappraiser.com/assets/img/photos/lanai-interior.webp","width":1200,"height":801},"breadcrumb":{"@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#breadcrumb"},"mainEntity":{"@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://hawaiiinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Questions by topic","item":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/"}],"@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process written into most property policies for resolving disagreements over the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and an award signed by any two of the three sets the amount."}},{"@type":"Question","name":"Is an insurance appraiser the same as a real estate appraiser?","acceptedAnswer":{"@type":"Answer","text":"No. A real estate appraiser estimates market value for a sale or refinance. An insurance appraiser values the cost to repair or replace damaged property under the terms of your policy."}},{"@type":"Question","name":"Can appraisal decide whether my claim is covered?","acceptedAnswer":{"@type":"Answer","text":"Generally no. Appraisal decides the amount of loss; coverage questions, denials and bad faith are legal issues for a Hawaii attorney."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either you or the insurer can, as long as the policy contains an appraisal clause. The demand should be in writing and reference the appraisal provision."}},{"@type":"Question","name":"Is the award binding?","acceptedAnswer":{"@type":"Answer","text":"On the amount of loss, an award signed by two of the three panel members is generally binding. Courts can set awards aside in limited circumstances, which is a question for an attorney."}},{"@type":"Question","name":"Who pays for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Each side typically pays its own appraiser, and umpire fees are commonly split equally. Check your policy, since wording varies."}},{"@type":"Question","name":"How are appraiser fees structured?","acceptedAnswer":{"@type":"Answer","text":"Fees may be hourly, flat or a percentage, depending on the appraiser and the claim. Get the arrangement in writing before you sign, and ask how travel to a neighbor island is billed."}},{"@type":"Question","name":"Is appraisal worth it for a small gap?","acceptedAnswer":{"@type":"Answer","text":"It depends on the size of the gap compared with the cost of the panel. Our claim gap fee estimator can help you see whether the numbers make sense before you start."}},{"@type":"Question","name":"Are inter-island travel costs extra?","acceptedAnswer":{"@type":"Answer","text":"Often, yes. Flights, rental cars and lodging for inspections or umpire visits on another island are commonly billed at cost or shared between the parties."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Simple residential disputes are often resolved in a few months. Large condo, hurricane or wildfire claims commonly take longer, especially when inspections span several islands."}},{"@type":"Question","name":"How long do I have to name my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies allow about 20 days after a demand, but windows vary. Read your policy and calendar the date the day you send or receive a demand."}},{"@type":"Question","name":"Does demanding appraisal stop my suit deadline?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Your policy’s suit-limitation clause may keep running during appraisal, so speak with a Hawaii attorney if that deadline is near."}},{"@type":"Question","name":"When is recoverable depreciation paid?","acceptedAnswer":{"@type":"Answer","text":"Commonly after repairs are completed and documented, within any time limit the policy sets. Keep invoices and photos of the finished work."}},{"@type":"Question","name":"What is HPIA?","acceptedAnswer":{"@type":"Answer","text":"The Hawaii Property Insurance Association is the state’s FAIR plan, best known for writing basic property coverage in Big Island lava zones 1 and 2 where private carriers often decline. Recent legislative sessions have also discussed its role for condo associations, so check the current status."}},{"@type":"Question","name":"How does a hurricane deductible work?","acceptedAnswer":{"@type":"Answer","text":"Many Hawaii policies apply a separate hurricane deductible, often a percentage of dwelling coverage, when a named hurricane causes the loss. Policies vary on what triggers it, so read your declarations and endorsements."}},{"@type":"Question","name":"Who handles a condo claim – the AOAO or me?","acceptedAnswer":{"@type":"Answer","text":"It depends on the damage. The AOAO’s master policy generally covers the building and common elements, while your HO-6 policy covers your unit’s interior, contents and possibly loss assessments; your governing documents define the line."}},{"@type":"Question","name":"Does lava zone matter for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Lava zone affects which insurers will write coverage and what perils a policy covers, not how appraisal works. If a lava-related loss is covered, appraisal can still resolve a dispute over the amount."}},{"@type":"Question","name":"Can I file a complaint with the Insurance Division?","acceptedAnswer":{"@type":"Answer","text":"Yes. The Insurance Division of the Department of Commerce and Consumer Affairs accepts consumer inquiries and complaints about insurers, separately from any appraisal."}},{"@type":"Question","name":"Which islands do you serve?","acceptedAnswer":{"@type":"Answer","text":"We work throughout Hawaii, including Oahu, Maui, the Big Island, Kauai, Molokai and Lanai. Neighbor-island inspections are scheduled around inter-island travel."}},{"@type":"Question","name":"Are you a law firm or a public adjuster?","acceptedAnswer":{"@type":"Answer","text":"Neither. We are independent appraisers focused on valuation, and we do not give legal advice or negotiate coverage."}},{"@type":"Question","name":"Can you review my insurer’s estimate before I demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes. An estimate review can show where the gaps are and whether appraisal looks worthwhile."}},{"@type":"Question","name":"Do you serve as an umpire?","acceptedAnswer":{"@type":"Answer","text":"Yes, when both sides and their appraisers agree on us, or when appointed. As an umpire we are neutral and have no role advocating for either party."}},{"@type":"Question","name":"How do I get started?","acceptedAnswer":{"@type":"Answer","text":"Call or email with your policy, the insurer’s estimate and any contractor bids. We will tell you plainly whether appraisal appears to fit your situation."}}],"@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#faq","isPartOf":{"@id":"https://hawaiiinsuranceappraiser.com/appraisal-questions-by-topic/#webpage"}}]}</script>
